(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.25)*18 + Math.cos(y*0.013-t*0.18)*12;
  const w1y = Math.cos(y*0.02-t*0.22)*16 + Math.sin(x*0.015+t*0.3)*10;
  const w2x = Math.sin(w1x*0.03+y*0.008+t*0.4)*8;
  const w2y = Math.cos(w1y*0.025+x*0.01-t*0.35)*7;
  const sx = x+w1x+w2x, sy = y+w1y+w2y;
  const src = [
    [240+Math.sin(t*0.6)*110,120+Math.cos(t*0.4)*60,0.08,2.0,0.0],
    [320+Math.cos(t*0.5)*100,160+Math.sin(t*0.7)*50,0.1,1.7,1.2],
    [240+Math.sin(t*0.3+2)*140,120+Math.cos(t*0.5+1)*90,0.06,2.3,2.4],
    [120+Math.cos(t*0.8+1)*80,180+Math.sin(t*0.6+3)*60,0.12,1.5,3.6],
    [360+Math.sin(t*0.4+4)*90,60+Math.cos(t*0.9+2)*70,0.07,2.6,4.8],
    [240+Math.cos(t*0.35+5)*120,200+Math.sin(t*0.55)*80,0.09,1.9,6.0],
    [80+Math.sin(t*0.45+3)*70,40+Math.cos(t*0.65+1)*50,0.11,2.1,1.8],
    [400+Math.cos(t*0.55+2)*60,200+Math.sin(t*0.75+4)*55,0.065,2.4,5.2]
  ];
  let aS=0,iS=0,hS=0;
  for(const[sX,sY,f,sp,ph]of src){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    aS+=Math.sin(d*f-t*sp+ph);
    iS+=Math.sin(d*f*0.7+t*sp*0.6+ph+1.5);
    hS+=Math.sin(d*f*1.3-t*sp*0.8+ph*2)*0.5;
  }
  const n=src.length,act=aS/n,inh=iS/n,harm=hS/n;
  const bg1=(Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2;
  const bg2=Math.sin((sx+sy)*0.12+t*2.5)*0.2+Math.sin((sx-sy)*0.1-t*2)*0.2;
  const bg3=Math.sin(sx*0.07+sy*0.05+t*1.8)*0.15+Math.sin(sx*0.05-sy*0.08-t*1.5)*0.15;
  const bg=bg1+bg2+bg3;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2),ang=Math.atan2(sy-cy,sx-cx);
  const spiral=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.4;
  const spiral2=Math.sin(dist*0.08+ang*2+t*0.8)*0.3+Math.sin(dist*0.03-ang*5-t*2)*0.2;
  const rd1=Math.tanh((act-inh*0.7+bg*0.3+spiral)*2.2);
  const rd2=Math.tanh((harm-act*0.5+bg*0.2+spiral2)*1.8);
  const reaction=rd1*0.7+rd2*0.3;
  const cell1=Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.3;
  const cell2=Math.sin(Math.sin(sx*0.08+sy*0.06)*Math.cos(sx*0.06-sy*0.08+t*0.7))*0.15;
  const blend=reaction*0.65+(cell1+cell2)*0.2+spiral2*0.15;
  const v=blend*0.5+0.5;
  const pal=[[12,22,78],[20,65,120],[28,120,135],[45,165,120],[140,190,70],[220,185,55],[215,130,65],[185,70,70],[130,40,80],[70,25,65],[12,22,78]];
  const idx=v*(pal.length-1),i=Math.min(idx|0,pal.length-2),f=idx-i;
  const lum=0.85+Math.sin(reaction*Math.PI)*0.15+Math.abs(rd2)*0.1;
  const edge=Math.abs(reaction)>0.65?1.12+Math.abs(reaction)*0.05:1.0;
  const chrom=Math.sin(harm*3.14)*0.08;
  return[
    Math.min(255,((pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*(1+chrom)*lum*edge))|0,
    Math.min(255,((pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge))|0,
    Math.min(255,((pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*(1-chrom)*lum*edge))|0
  ];
}
